describe('Product Sorting by Price', () => {
    beforeEach(() => {
        cy.visit('https://www.saucedemo.com');
        cy.get('[data-test="username"]').type('standard_user');
        cy.get('[data-test="password"]').type('secret_sauce');
        cy.get('[data-test="login-button"]').click();
    });

    it('should sort products by price in ascending order (happy path)', () => {
        cy.get('[data-test="product-sort-container"]').select('lohi');
        cy.get('.inventory_item_price').then(($prices) => {
            const priceArray = $prices.toArray().map(price => parseFloat(price.innerText.replace('$', '')));
            const sortedPriceArray = [...priceArray].sort((a, b) => a - b);
            expect(priceArray).to.deep.equal(sortedPriceArray);
        });
    });

    it('should not sort products if the sort option is not selected', () => {
        cy.get('.inventory_item_price').then(($prices) => {
            const initialPriceArray = $prices.toArray().map(price => parseFloat(price.innerText.replace('$', '')));
            cy.get('[data-test="product-sort-container"]').select('az'); // Selecting a different sort option
            cy.get('.inventory_item_price').then(($newPrices) => {
                const newPriceArray = $newPrices.toArray().map(price => parseFloat(price.innerText.replace('$', '')));
                expect(initialPriceArray).to.deep.equal(newPriceArray);
            });
        });
    });
});
